            # Roll back the uncommitted entry from the primary log
            # so that no orphaned, uncommitted state lingers
            self.log.pop()
            return False

        # Quorum reached: atomically commit the state mutation
        self.state[key] = value
        self.commit_index = entry_idx
        return True

